python3 - <<'EOF'
import json
with open('batches/batch_0035.json', encoding='utf-8') as f:
    data = json.load(f)

def try_fix(s):
    if not s:
        return s
    try:
        fixed = s.encode('latin1').decode('utf-8')
        return fixed
    except Exception:
        try:
            return s.encode('latin1', errors='ignore').decode('utf-8', errors='ignore')
        except Exception:
            return s

def looks_mojibake(s):
    if not s:
        return False
    # common mojibake marker chars
    markers = ['ã', 'å', 'æ', 'ç', 'è', 'é', 'ê']
    count = sum(s.count(m) for m in markers)
    return count > len(s) * 0.15

out = []
for item in data:
    for field in ['title','desc','body']:
        val = item.get(field,'')
        if looks_mojibake(val):
            item[field] = try_fix(val)
    out.append(item)

with open('batch_0035_fixed2.json','w',encoding='utf-8') as f:
    json.dump(out, f, ensure_ascii=False, indent=1)
print("done", len(out))
EOF
